import java.util.*;

public class Main {
    static int shared = 0; // static field lives on the heap: all threads see it

    public static void main(String[] args) throws Exception {
        List<String> log = Collections.synchronizedList(new ArrayList<>());
        Runnable task = () -> {
            int local = 0; // local variable lives on this thread's own stack
            for (int i = 0; i < 3; i++) local++;
            synchronized (Main.class) { shared += local; }
            log.add("local=" + local);
        };
        Thread t1 = new Thread(task), t2 = new Thread(task);
        t1.start(); t2.start();
        t1.join(); t2.join();
        // each thread had its own 'local' (3), but 'shared' got both updates
        System.out.println(log);
        System.out.println("shared = " + shared);
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Runnable task = () ->
            System.out.println("task runs on: " + Thread.currentThread().getName());

        Thread t = new Thread(task, "worker");
        t.run();            // plain method call: runs on main, no new thread
        t.start();          // creates a new thread, which then calls run()
        t.join();

        try {
            t.start();      // a thread can be started only once
        } catch (IllegalThreadStateException e) {
            System.out.println("second start(): " + e.getClass().getSimpleName());
        }
    }
}

public class Main {
    static final Object lock = new Object();

    public static void main(String[] args) throws Exception {
        Thread t = new Thread(() -> {
            try { Thread.sleep(300); } catch (InterruptedException e) { }
            synchronized (lock) { }
        });
        System.out.println("before start : " + t.getState());       // NEW
        synchronized (lock) {                 // main holds the monitor
            t.start();
            Thread.sleep(100);
            System.out.println("sleeping     : " + t.getState());   // TIMED_WAITING
            Thread.sleep(500);
            System.out.println("lock held    : " + t.getState());   // BLOCKED
        }
        t.join();
        System.out.println("after join   : " + t.getState());       // TERMINATED

        Thread w = new Thread(() -> {
            synchronized (lock) { try { lock.wait(); } catch (InterruptedException e) { } }
        });
        w.start();
        Thread.sleep(200);
        System.out.println("in wait()    : " + w.getState());       // WAITING
        w.interrupt(); w.join();
    }
}

public class Main {
    private int count = 0;
    private final Object lock = new Object(); // private lock object

    void increment() {
        synchronized (lock) { count++; } // read-modify-write is now atomic
    }

    public static void main(String[] args) throws Exception {
        Main m = new Main();
        Runnable r = () -> { for (int i = 0; i < 100_000; i++) m.increment(); };
        Thread a = new Thread(r), b = new Thread(r);
        a.start(); b.start();
        a.join(); b.join();      // join gives happens-before, so main sees the final value
        System.out.println("expected = 200000");
        System.out.println("actual   = " + m.count);
    }
}

public class Main {
    static volatile boolean running = true; // without volatile the loop may never see false

    public static void main(String[] args) throws Exception {
        long[] spins = new long[1];
        Thread worker = new Thread(() -> {
            while (running) {       // volatile read each iteration
                spins[0]++;
            }
            System.out.println("worker saw running=false and stopped");
        });
        worker.start();
        Thread.sleep(100);
        running = false;            // volatile write publishes the change
        worker.join();              // join also makes spins[0] visible
        System.out.println("worker did work: " + (spins[0] > 0));
    }
}

public class Main {
    static int data = 0;
    static volatile boolean ready = false;

    public static void main(String[] args) throws Exception {
        Thread reader = new Thread(() -> {
            while (!ready) { }           // volatile read (step 3)
            System.out.println("reader sees data = " + data); // guaranteed 42
        });
        reader.start();
        Thread.sleep(50);
        data = 42;     // 1. plain write, before the volatile write in program order
        ready = true;  // 2. volatile write happens-before the reader's read of true
        reader.join();
        // chain: program order -> volatile write/read -> program order => visibility
    }
}

public class Main {
    private static volatile Main instance; // volatile makes the publication safe

    private Main() { System.out.println("constructed once"); }

    static Main get() {
        Main local = instance;             // one volatile read on the fast path
        if (local == null) {
            synchronized (Main.class) {
                local = instance;
                if (local == null) instance = local = new Main();
            }
        }
        return local;
    }

    static class Holder { // alternative: lazy and thread-safe via class init
        static final Main INSTANCE = new Main();
    }

    public static void main(String[] args) throws Exception {
        Thread[] ts = new Thread[4];
        Main[] seen = new Main[4];
        for (int i = 0; i < 4; i++) {
            final int k = i;
            ts[i] = new Thread(() -> seen[k] = get());
            ts[i].start();
        }
        for (Thread t : ts) t.join();
        boolean same = true;
        for (Main m : seen) same &= (m == seen[0]);
        System.out.println("all threads got the same instance: " + same);
    }
}

public class Main {
    private int value;
    private boolean full = false;

    synchronized void put(int v) throws InterruptedException {
        while (full) wait();        // re-check the condition after every wake-up
        value = v; full = true;
        notifyAll();                // wake threads waiting for a different condition
    }

    synchronized int take() throws InterruptedException {
        while (!full) wait();       // wait() releases the monitor while waiting
        full = false;
        notifyAll();
        return value;
    }

    public static void main(String[] args) throws Exception {
        Main box = new Main();
        Thread consumer = new Thread(() -> {
            try {
                for (int i = 0; i < 3; i++) System.out.println("took " + box.take());
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });
        consumer.start();
        for (int i = 1; i <= 3; i++) box.put(i * 10);
        consumer.join();
    }
}

import java.util.*;

public class Main {
    private final Deque<Integer> q = new ArrayDeque<>();
    private final int capacity;
    Main(int capacity) { this.capacity = capacity; }

    synchronized void put(int x) throws InterruptedException {
        while (q.size() == capacity) wait();   // buffer full: producer waits
        q.addLast(x);
        notifyAll();                           // wake consumers (and producers)
    }

    synchronized int take() throws InterruptedException {
        while (q.isEmpty()) wait();            // buffer empty: consumer waits
        int x = q.removeFirst();
        notifyAll();
        return x;
    }

    public static void main(String[] args) throws Exception {
        Main buf = new Main(2);                // tiny capacity forces waiting
        int[] sum = new int[1];
        Thread consumer = new Thread(() -> {
            try { for (int i = 0; i < 10; i++) sum[0] += buf.take(); }
            catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });
        consumer.start();
        for (int i = 1; i <= 10; i++) buf.put(i);
        consumer.join();
        System.out.println("produced 1..10, consumed sum = " + sum[0]); // 55
    }
}

public class Main {
    static class Account {
        final int id; int balance;
        Account(int id, int balance) { this.id = id; this.balance = balance; }
    }

    // Always lock the account with the smaller id first: no circular wait possible
    static void transfer(Account a, Account b, int amount) {
        Account first = a.id < b.id ? a : b;
        Account second = a.id < b.id ? b : a;
        synchronized (first) {
            synchronized (second) {
                a.balance -= amount;
                b.balance += amount;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        Account x = new Account(1, 1000), y = new Account(2, 1000);
        Thread t1 = new Thread(() -> { for (int i = 0; i < 1000; i++) transfer(x, y, 1); });
        Thread t2 = new Thread(() -> { for (int i = 0; i < 1000; i++) transfer(y, x, 1); });
        t1.start(); t2.start();      // opposite directions: deadlocks without ordering
        t1.join(); t2.join();
        System.out.println("x = " + x.balance + ", y = " + y.balance + ", total = " + (x.balance + y.balance));
    }
}

import java.util.concurrent.locks.*;

public class Main {
    static final ReentrantLock a = new ReentrantLock(), b = new ReentrantLock();

    static void work(String name, ReentrantLock first, ReentrantLock second) {
        java.util.Random rnd = new java.util.Random(name.hashCode());
        while (true) {
            first.lock();
            try {
                if (second.tryLock()) {          // try, never block while holding 'first'
                    try { System.out.println(name + " got both locks"); return; }
                    finally { second.unlock(); }
                }
            } finally { first.unlock(); }        // back off: release what we hold
            try { Thread.sleep(1 + rnd.nextInt(5)); } // random pause breaks lockstep
            catch (InterruptedException e) { return; }
        }
    }

    public static void main(String[] args) throws Exception {
        Thread t1 = new Thread(() -> work("T1", a, b));
        Thread t2 = new Thread(() -> work("T2", b, a)); // opposite order
        t1.start(); t2.start();
        t1.join(); t2.join();
        System.out.println("both finished");
    }
}

import java.util.concurrent.atomic.*;

public class Main {
    static final AtomicInteger stock = new AtomicInteger(5);
    static final AtomicInteger sold = new AtomicInteger(0);

    // Each call is atomic, but "get() > 0 then decrement" as a pair is NOT:
    // two threads could both see 1 and both sell. Fix: one atomic compare-and-set loop.
    static boolean buy() {
        while (true) {
            int cur = stock.get();
            if (cur == 0) return false;
            if (stock.compareAndSet(cur, cur - 1)) return true; // check and act as one step
        }
    }

    public static void main(String[] args) throws Exception {
        Thread[] ts = new Thread[10];
        for (int i = 0; i < 10; i++) {
            ts[i] = new Thread(() -> { if (buy()) sold.incrementAndGet(); });
            ts[i].start();
        }
        for (Thread t : ts) t.join();
        System.out.println("10 buyers, stock 5 -> sold = " + sold.get() + ", left = " + stock.get());
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Thread worker = new Thread(() -> {
            int ticks = 0;
            try {
                while (!Thread.currentThread().isInterrupted()) { // check the flag in the loop
                    ticks++;
                    Thread.sleep(20); // blocking call throws if interrupted
                }
            } catch (InterruptedException e) {
                // the flag was cleared when the exception was thrown: restore it
                Thread.currentThread().interrupt();
                System.out.println("interrupted while sleeping, flag restored: "
                        + Thread.currentThread().isInterrupted());
            } finally {
                System.out.println("cleanup done, ticks > 0: " + (ticks > 0));
            }
        });
        worker.start();
        Thread.sleep(100);
        worker.interrupt();        // a polite request, not a forced stop
        worker.join();
        System.out.println("worker state: " + worker.getState());
    }
}
